using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "GoddessCartoucheOmenData", menuName = "Data/Battle/Omens System/Omen Data/Sothis/GoddessCartoucheOmenData")]
public class GoddessCartoucheOmenData : OmenData
{
	[Header("Goddess Cartouche Omen")]
	[SerializeField]
	private ReliefDefaultEffectAction reliefDefaultEffectAction;

	[SerializeField]
	private BattleActionAreaEnemyOmenLogic battleActionAreaEnemyOmenLogic;

	[SerializeField]
	private int reliefAmount;

	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<SothisOmensHandler>.Instance.GoddessCartoucheOmenAction = delegate
		{
			battleActionAreaEnemyOmenLogic.ActivateOmen(reliefDefaultEffectAction, reliefAmount, null, null);
			omenInstance.EnqueueOmenFeedbackAndPlay();
		};
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<SothisOmensHandler>.Instance.GoddessCartoucheOmenAction = null;
	}

	public override string OmenConvertedDescription()
	{
		return string.Concat(GetOmenRawLocalizedDescription(), str2: reliefDefaultEffectAction.GetActionDescription(reliefAmount).LowercaseFirst(), str1: ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace());
	}
}
